; Written by hand, not generated by c64-source: source.ts generate keeps this file.
; Boot: shows the Datasoft title picture, then starts the game through the generated loader.
;
; The Datasoft release showed this picture before the game started. No release holds it in the
; game bytes: the TBC crack shows it in its intro (with "CRACKED BY TBC" in the bitmap and one
; screen colour for all cells), and it is not in SAEGER or DC. title_picture.kla is the clean
; picture: the TBC bitmap, without the TBC text, with the cell colours of the original screen.
; tools/pack_title_picture.py packs it to title_picture.rle.
;
; Build (c64-assembler): assembler.ts build src boot.asm --out build/bruce_lee_boot.prg
; The switches apply as for loader.asm: config.asm gives their values, and --release <label>
; gives the values of a release. TITLE_PICTURE = 0 in config.asm leaves out the picture: the
; boot then only starts the loader.
;
; Memory while the picture shows: this code at $0801, the loader at $0C01, the packed picture
; after it. The picture unpacks to VIC bank 3: bitmap $E000, screen $CC00, colour RAM $D800.
; A key, the fire button of port 1 or 2, or 10 seconds start the game. Then boot_mover (at $033C)
; moves the loader down to $0801 and jumps to its entry at $080D. The loader writes its entry
; state over $0002-$03FE, so the boot leaves no code there.

!cpu 6510
!source "switches.asm"                  ; TITLE_PICTURE; loader.asm reads the same values again

boot_src        = $fb                   ; 2 bytes: read pointer
boot_dst        = $fd                   ; 2 bytes: write pointer
boot_bitmap     = $e000
boot_screen     = $cc00
boot_colour_ram = $d800
boot_wait_frames = 500                  ; 10 seconds (PAL)
boot_loader_entry = $080d               ; loader_stub of loader.asm

* = $0801
        !byte $0b,$08,$0a,$00,$9e,$32,$30,$36,$31,$00,$00,$00 ; 10 SYS 2061

!zone boot {
boot_start
        lda #$36                        ; BASIC ROM off: the file runs into $A000-$BFFF
        sta $01
!if TITLE_PICTURE {
        jsr boot_show_picture
        jsr boot_wait
}
        sei
        lda #$0b                        ; screen off
        sta $d011
        ldx #boot_mover_end - boot_mover_run - 1
.copy_mover
        lda boot_mover_src,x
        sta boot_mover_run,x
        dex
        bpl .copy_mover
        lda #<boot_payload
        sta boot_src
        lda #>boot_payload
        sta boot_src+1
        lda #<$0801
        sta boot_dst
        lda #>$0801
        sta boot_dst+1
        ldx #>(boot_payload_end - boot_payload + $ff)
        jmp boot_mover_run

!if TITLE_PICTURE {
; Unpacks the picture to VIC bank 3 and shows it.
boot_show_picture
        lda #$0b                        ; screen off while the picture unpacks
        sta $d011
        lda #<boot_picture
        sta boot_src
        lda #>boot_picture
        sta boot_src+1
        ldy #0
        jsr .get
        sta .escape+1
        jsr .get
        sta $d021                       ; background colour
        lda #$0e                        ; border: light blue
        sta $d020
        lda #<boot_bitmap
        ldx #>boot_bitmap
        jsr .unpack
        lda #<boot_screen
        ldx #>boot_screen
        jsr .unpack
        lda #<boot_colour_ram
        ldx #>boot_colour_ram
        jsr .unpack
        lda $dd00                       ; VIC bank 3 ($C000-$FFFF)
        and #$fc
        sta $dd00
        lda #$38                        ; screen $CC00, bitmap $E000
        sta $d018
        lda #$18                        ; multicolour, 40 columns
        sta $d016
        lda #$3b                        ; bitmap mode, screen on
        sta $d011
        rts

; Unpacks one RLE stream to A (low), X (high). Y stays 0.
.unpack
        sta boot_dst
        stx boot_dst+1
.next   jsr .get
.escape cmp #$00                        ; the escape byte of the file
        bne .literal
        jsr .get                        ; the count of a run, 0 = end of the stream
        tax                             ; sets Z from the count (.get leaves Z of its INC)
        beq .done
        jsr .get
.run    jsr .put
        dex
        bne .run
        beq .next
.literal
        jsr .put
        jmp .next
.done   rts

.get    lda (boot_src),y
        inc boot_src
        bne +
        inc boot_src+1
+       rts

.put    sta (boot_dst),y
        inc boot_dst
        bne +
        inc boot_dst+1
+       rts

; Waits for a key (the KERNAL key queue), the fire button of port 2 ($DC00) or port 1 ($DC01),
; or boot_wait_frames frames.
boot_wait
        lda #0
        sta $c6                         ; empty the key queue
        lda #<boot_wait_frames
        sta boot_dst
        lda #>boot_wait_frames
        sta boot_dst+1
.frame  lda $d012                       ; wait for raster line 251
        cmp #251
        bne .frame
.line   lda $d012
        cmp #251
        beq .line
        lda $c6
        bne .end
        lda $dc00
        and #$10
        beq .end
        lda $dc01
        and #$10
        beq .end
        lda boot_dst
        bne +
        dec boot_dst+1
+       dec boot_dst
        lda boot_dst
        ora boot_dst+1
        bne .frame
.end    lda #0
        sta $c6
        rts
}

; Moves X pages from boot_src to boot_dst and starts the loader. It runs at $033C, because the
; move writes over the boot code. The source is above the target, so a forward copy is safe.
boot_mover_src
!pseudopc $033c {
boot_mover_run
        ldy #0
.move   lda (boot_src),y
        sta (boot_dst),y
        iny
        bne .move
        inc boot_src+1
        inc boot_dst+1
        dex
        bne .move
        jmp boot_loader_entry
boot_mover_end
}
}

!if * > $0c01 { !error "the boot code runs into the loader at $0C01" }
* = $0c01
boot_payload
!pseudopc $0801 {
!source "loader.asm"
}
boot_payload_end

!if TITLE_PICTURE {
boot_picture
        !bin "title_picture.rle"
}
!if * > boot_screen { !error "the boot file runs into the screen of the picture at $CC00" }
